<script setup>
import { ref, computed } from 'vue'
import Icon from './Icon.vue'
import ProcessCard from './ProcessCard.vue'
import { api } from '../api.js'

// A definition generated by process-gpt's bpmn-process-generation-skill, before and after saving.
const props = defineProps({ msg: Object })
const c = computed(() => props.msg.content)
const pd = computed(() => c.value.contract?.processDefinition || {})
const els = computed(() => pd.value.elements || [])
const acts = computed(() => els.value.filter((e) => e.elementType === 'Activity'))
const forms = computed(() => c.value.contract?.forms || [])
const agents = computed(() => c.value.contract?.agents || [])
const busy = ref(false)
const err = ref('')
const isAgent = (a) => (a.agentMode && a.agentMode !== 'none') || a.orchestration

async function save() {
  busy.value = true
  err.value = ''
  try { await api(`/drafts/${props.msg.id}/save`, { method: 'POST' }) } catch (e) { err.value = '저장하지 못했어요. ' + e.message.slice(0, 120) } finally { busy.value = false }
}
</script>

<template>
  <ProcessCard v-if="c.defId" :msg="{ ...msg, content: { ...c, name: pd.processDefinitionName, mode: 'view' } }" />
  <div v-else class="draft">
    <span class="badge">새 프로세스 초안</span>
    <h3 class="serif">{{ pd.processDefinitionName }}</h3>
    <p v-if="pd.description" class="desc">{{ pd.description }}</p>
    <ol class="acts">
      <li v-for="(a, i) in acts" :key="a.id" :style="{ '--i': i }">
        <span class="n">{{ i + 1 }}</span>
        <div><b>{{ a.name }}</b><small><Icon :name="isAgent(a) ? 'panel' : 'hand'" :size="12" /> {{ a.role }}</small></div>
      </li>
    </ol>
    <p class="meta">역할 {{ (pd.roles || []).length }} · 폼 {{ forms.length }}<span v-if="agents.length"> · 에이전트 {{ agents.length }}</span></p>
    <button class="dark-btn" :disabled="busy" @click="save">{{ busy ? '저장하는 중…' : '프로세스로 저장' }}</button>
    <p v-if="err" class="err">{{ err }}</p>
  </div>
</template>

<style scoped>
.draft { width: 424px; max-width: 100%; border-radius: 24px; padding: 20px 20px 18px; background: var(--bubble-agent-bg); -webkit-backdrop-filter: blur(50px); backdrop-filter: blur(50px); box-shadow: var(--shadow-card); display: flex; flex-direction: column; gap: 8px; }
.badge { font-size: 12px; color: var(--text-secondary); letter-spacing: .04em; }
h3 { margin: 0; font-size: 23px; font-weight: 400; line-height: 1.3; }
.desc { margin: 0; font-size: 14px; line-height: 1.5; color: var(--text-secondary); }
.acts { list-style: none; margin: 6px 0 0; padding: 12px; border-radius: 16px; background: var(--field-bg); display: flex; flex-direction: column; gap: 10px; }
.acts li { display: grid; grid-template-columns: 26px 1fr; gap: 10px; align-items: start; animation: blur-in .4s var(--spring) both; animation-delay: calc(var(--i) * 60ms); }
.n { width: 24px; height: 24px; border-radius: 9999px; display: grid; place-items: center; font-size: 12px; background: var(--ink); color: var(--ink-inverse); }
.acts b { font-weight: 500; font-size: 15px; display: block; }
.acts small { display: flex; align-items: center; gap: 5px; color: var(--text-secondary); font-size: 12.5px; margin-top: 2px; }
.meta { margin: 2px 2px 4px; font-size: 13px; color: var(--text-secondary); }
:root[data-theme="dark"] .dark-btn { background: #f5f5f7; color: #1d1d1f; }
.err { color: var(--color-error); font-size: 13px; margin: 0; }
</style>
